  override fun invoke(resource: Resource<T>): Resource<T> {
    var container = getContainerFromSpec(resource)
    if (container is ContainerWithDigest) {
      log.debug("Container already has a digest, no need to resolve tag: $container")
      return resource
    }
    container = container as ContainerWithVersionedTag
    val account = getAccountFromSpec(resource)
    val deliveryConfig = deliveryConfigRepository.deliveryConfigFor(resource.id)
    val environment = deliveryConfigRepository.environmentFor(resource.id)
    val tag: String = if (deliveryConfig != null && environment != null) {
      log.debug("Resolving tag for image '${container.repository()}' in delivery config '${deliveryConfig.name}' environment '${environment.name}'")
      findTagGivenDeliveryConfig(deliveryConfig, environment, container.toArtifact())
    } else {
      log.debug("Resolving tag for image '${container.repository()}' using tag versioning strategy '${container.tagVersionStrategy}'")
      findTagGivenStrategy(account, container)
    }

    val newContainer = getContainer(account, container, tag)
    return updateContainerInSpec(resource, newContainer)
  }

  fun findTagGivenDeliveryConfig(deliveryConfig: DeliveryConfig, environment: Environment, artifact: DeliveryArtifact): String {
    val tag = artifactRepository.latestVersionApprovedIn(
      deliveryConfig,
      artifact,
      environment.name,
      artifact.statuses
    )
    if (tag == null) {
      log.debug("No version of artifact '${artifact.name}' has been approved in environment '${environment.name}', unable to resolve image tag")
    }
    return tag ?: throw NoDockerImageSatisfiesConstraints(artifact.name, environment.name)
  }

  fun findTagGivenStrategy(
    account: String,
    container: ContainerWithVersionedTag
  ): String {
    val tags = getTags(account, container.organization, container.image)
    log.debug("Found ${tags.size} tags for image '${container.repository()}'")
    val tag = tags.sortedWith(TagComparator(container.tagVersionStrategy, container.captureGroupRegex)).first()
    log.debug("Selecting first tag '$tag' for image '${container.repository()}' using strategy '${container.tagVersionStrategy}'")
    return tag
  }

  fun getContainer(
    account: String,
    container: Container,
    tag: String
  ): ContainerWithDigest {
    log.debug("Resolving digest for image '${container.repository()}' tag '$tag'")
    val digest = getDigest(account, container.organization, container.image, tag)
    log.debug("Resolved digest '$digest' for image '${container.repository()}' tag '$tag'")
    return ContainerWithDigest(
      organization = container.organization,
      image = container.image,
      digest = digest
    )
  }

  private fun ContainerWithVersionedTag.toArtifact() =
    DockerArtifact(repository(), tagVersionStrategy, captureGroupRegex)
}

